ext("← Voltar")};Text(selected!!,fontWeight=FontWeight.Black,modifier=Modifier.weight(1f));TextButton({input=selected!!;rename=true;dialog=true}){Text("Renomear")}};Text("Toque para adicionar ou remover",color=MpMuted,modifier=Modifier.padding(bottom=10.dp));LazyColumn(verticalArrangement=Arrangement.spacedBy(8.dp)){items(works,key={it.id}){work->Surface(Modifier.fillMaxWidth().clickable{store.toggle(selected!!,work.id);members=store.works(selected!!)},color=MpSurface,shape=RoundedCornerShape(14.dp)){Row(Modifier.padding(10.dp),verticalAlignment=Alignment.CenterVertically){AsyncImage(work.cover,work.title,Modifier.size(52.dp).clip(RoundedCornerShape(10.dp)),contentScale=ContentScale.Crop);Text(work.title,fontWeight=FontWeight.Bold,modifier=Modifier.weight(1f).padding(horizontal=10.dp),maxLines=1);Checkbox(work.id in members,{store.toggle(selected!!,work.id);members=store.works(selected!!)})}}}}}}
