   "Comentários"->item{CommentsSection("obra",work.id,"",Modifier.padding(horizontal=12.dp,vertical=18.dp))}
   else->{item{Column(Modifier.padding(horizontal=12.dp,vertical=10.dp)){Button(onClick={scope.launch{if(chapters.isEmpty())return@launch;downloadingAll=true;bulkError="";bulkMessage="Preparando downloads…";val pending=chapters.filter{offlineStore.localPages(work.id,it.id).isEmpty()};if(pending.isEmpty()){bulkProgress=100;bulkMessage="Todos os capítulos já estão baixados."}else{var completed=0;for(chapter in pending){bulkMessage="Baixando ${chapter.label}";val result=runCatching{val pages=repository.pages(work.id,chapter.id);offlineStore.download(work,chapter,pages){pageProgress->bulkProgress=((completed*100)+pageProgress)/pending.size}};if(result.isFailure){bulkError="Alguns capítulos não puderam ser baixados.";break};completed++;bulkProgress=(completed*100)/pending.size};if(bulkError.isBlank())bulkMessage="Download concluído."};downloadingAll=false}},enabled=!loading&&!downloadingAll&&chapters.isNotEmpty(),modifier=Modifier.fillMaxWidth(),shape=RoundedCornerShape(15.dp)){Text(if(downloadingAll)"Baixando… $bulkProgress%" else "⇣ Baixar todos os capítulos",fontWeight=FontWeight.Black)};if(downloadingAll)LinearProgressIndicator(progress={bulkProgress/100f},modifier=Modifier.fillMaxWidth().padding(top=8.dp));if(bulkMessage.isNotBlank())Text(bulkMessage,color=if(bulkError.isBlank())MpAccent2 else MaterialTheme.colorScheme.error,modifier=Modifier.padding(top=7.dp))}};if(loading)item{LinearProgressIndicator(Modifier.fillMaxWidth().padding(horizontal=16.dp))};items(chapters,key={it.id}){c->ChapterRow(c,progress[c.id],offlineStore.localPages(work.id,c.id).isNotEmpty()){reading=c}}}
  }
 }
